/**
 * koka-encode.ts
 *
 * Koka name encoding utilities matching Common/Name.hs asciiEncode.
 *
 * There are two encoding modes:
 *   - Module path → filename: '/' becomes '_' (module separator flattening)
 *   - Identifier → JS export: '/' becomes '_fs_', '-' before alnum becomes '_'
 */

/**
 * Encode a Koka module path to a flat filename.
 * Used to find the generated .mjs file for a given module name.
 *
 * Examples: "std/core" → "std_core", "garsia-wachs" → "garsia_dash_wachs"
 */
export function kokaModuleToFilename(moduleName: string): string {
  let result = '';
  for (let i = 0; i < moduleName.length; i++) {
    const c = moduleName[i];
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')) {
      result += c;
    } else if (c === '/') {
      result += '_';
    } else if (c === '-') {
      result += '_dash_';
    } else if (c === '_') {
      result += '__';
    } else if (c === '.') {
      result += '_dot_';
    } else {
      result += c;
    }
  }
  return result;
}

/**
 * Encode a Koka identifier as it appears in JS exports (isModule=false encoding).
 * Used to find the entry function name in the generated module.
 *
 * Examples: "test/fib" → "test_fs_fib", "my-func" → "my_func"
 */
export function kokaIdentToJsExport(name: string): string {
  let result = '';
  for (let i = 0; i < name.length; i++) {
    const c = name[i];
    const next = name[i + 1] ?? ' ';
    if (/[a-zA-Z0-9]/.test(c)) {
      result += c;
    } else if (c === '/') {
      result += '_fs_';
    } else if (c === '-' && /[a-zA-Z0-9]/.test(next)) {
      result += '_';
    } else if (c === '-') {
      result += '_dash_';
    } else if (c === '_') {
      result += '__';
    } else if (c === '.') {
      result += '_dot_';
    } else {
      result += c;
    }
  }
  return result;
}
